    '@import "tailwindcss";\n@import "tw-animate-css";\n@import "shadcn/tailwind.css";\n@import "./app.css";\n\n@custom-variant dark (&:is(.dark *));\n\n/* Default starter theme — "porcelain ledger": cool porcelain surfaces, ink\n   primary, bronze accent and focus. Red and green are kept out of the chrome so\n   generated apps can reserve them for market up/down semantics. Theme overrides\n   require an explicit theme in the build record. */\n\n:root {\n  --background: oklch(0.982 0.004 240);\n  --foreground: oklch(0.22 0.018 255);\n  --card: oklch(1 0 0);\n  --card-foreground: oklch(0.22 0.018 255);\n  --popover: oklch(1 0 0);\n  --popover-foreground: oklch(0.22 0.018 255);\n  --primary: oklch(0.3 0.03 255);\n  --primary-foreground: oklch(0.98 0.005 240);\n  --secondary: oklch(0.955 0.008 250);\n  --secondary-foreground: oklch(0.3 0.03 255);\n  --muted: oklch(0.96 0.007 250);\n  --muted-foreground: oklch(0.5 0.022 255);\n  --accent: oklch(0.945 0.028 80);\n  --accent-foreground: oklch(0.35 0.055 70);\n  --destructive: oklch(0.55 0.22 27);\n  --border: oklch(0.9 0.012 250);\n  --input: oklch(0.9 0.012 250);\n  --ring: oklch(0.55 0.07 75);\n  --chart-1: oklch(0.55 0.12 250);\n  --chart-2: oklch(0.62 0.11 170);\n  --chart-3: oklch(0.72 0.13 75);\n  --chart-4: oklch(0.55 0.16 20);\n  --chart-5: oklch(0.58 0.12 310);\n  --radius: 0.625rem;\n  --sidebar: oklch(0.965 0.007 240);\n  --sidebar-foreground: oklch(0.22 0.018 255);\n  --sidebar-primary: oklch(0.3 0.03 255);\n  --sidebar-primary-foreground: oklch(0.98 0.005 240);\n  --sidebar-accent: oklch(0.94 0.01 250);\n  --sidebar-accent-foreground: oklch(0.22 0.018 255);\n  --sidebar-border: oklch(0.9 0.012 250);\n  --sidebar-ring: oklch(0.55 0.07 75);\n}\n\n.dark {\n  --background: oklch(0.17 0.015 255);\n  --foreground: oklch(0.95 0.005 240);\n  --card: oklch(0.215 0.018 255);\n  --card-foreground: oklch(0.95 0.005 240);\n  --popover: oklch(0.215 0.018 255);\n  --popover-foreground: oklch(0.95 0.005 240);\n  --primary: oklch(0.86 0.06 80);\n  --primary-foreground: oklch(0.2 0.04 80);\n  --secondary: oklch(0.27 0.018 255);\n  --secondary-foreground: oklch(0.95 0.005 240);\n  --muted: oklch(0.26 0.018 255);\n  --muted-foreground: oklch(0.72 0.015 250);\n  --accent: oklch(0.3 0.025 255);\n  --accent-foreground: oklch(0.95 0.005 240);\n  --destructive: oklch(0.7 0.19 22);\n  --border: oklch(1 0 0 / 12%);\n  --input: oklch(1 0 0 / 15%);\n  --ring: oklch(0.75 0.08 80);\n  --chart-1: oklch(0.7 0.12 250);\n  --chart-2: oklch(0.72 0.11 170);\n  --chart-3: oklch(0.8 0.12 80);\n  --chart-4: oklch(0.68 0.16 20);\n  --chart-5: oklch(0.7 0.12 310);\n  --sidebar: oklch(0.2 0.015 255);\n  --sidebar-foreground: oklch(0.95 0.005 240);\n  --sidebar-primary: oklch(0.86 0.06 80);\n  --sidebar-primary-foreground: oklch(0.2 0.04 80);\n  --sidebar-accent: oklch(0.27 0.02 255);\n  --sidebar-accent-foreground: oklch(0.95 0.005 240);\n  --sidebar-border: oklch(1 0 0 / 12%);\n  --sidebar-ring: oklch(0.75 0.08 80);\n}\n\n@theme inline {\n  --font-sans: "Inter Variable", sans-serif;\n  --color-sidebar-ring: var(--sidebar-ring);\n  --color-sidebar-border: var(--sidebar-border);\n  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);\n  --color-sidebar-accent: var(--sidebar-accent);\n  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);\n  --color-sidebar-primary: var(--sidebar-primary);\n  --color-sidebar-foreground: var(--sidebar-foreground);\n  --color-sidebar: var(--sidebar);\n  --color-chart-5: var(--chart-5);\n  --color-chart-4: var(--chart-4);\n  --color-chart-3: var(--chart-3);\n  --color-chart-2: var(--chart-2);\n  --color-chart-1: var(--chart-1);\n  --color-ring: var(--ring);\n  --color-input: var(--input);\n  --color-border: var(--border);\n  --color-destructive: var(--destructive);\n  --color-accent-foreground: var(--accent-foreground);\n  --color-accent: var(--accent);\n  --color-muted-foreground: var(--muted-foreground);\n  --color-muted: var(--muted);\n  --color-secondary-foreground: var(--secondary-foreground);\n  --color-secondary: var(--secondary);\n  --color-primary-foreground: var(--primary-foreground);\n  --color-primary: var(--primary);\n  --color-popover-foreground: var(--popover-foreground);\n  --color-popover: var(--popover);\n  --color-card-foreground: var(--card-foreground);\n  --color-card: var(--card);\n  --color-foreground: var(--foreground);\n  --color-background: var(--background);\n  --radius-sm: calc(var(--radius) - 4px);\n  --radius-md: calc(var(--radius) - 2px);\n  --radius-lg: var(--radius);\n  --radius-xl: calc(var(--radius) + 4px);\n  --radius-2xl: calc(var(--radius) + 8px);\n  --radius-3xl: calc(var(--radius) + 12px);\n  --radius-4xl: calc(var(--radius) + 16px);\n}\n\n@layer base {\n  * {\n    @apply border-border outline-ring/50;\n  }\n  body {\n    @apply font-sans bg-background text-foreground;\n  }\n  html {\n    @apply font-sans;\n  }\n}\n\n@layer base {\n  html {\n    scrollbar-gutter: stable;\n  }\n  body {\n    margin: 0;\n  }\n}\n',
